import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
items = json.loads((ROOT / 'tip-review-input-DGT302.json').read_text(encoding='utf-8'))
judgements = {}
changes = {}

def keep(ids, why):
    for n in str(ids).split(','):
        ident = f'DGT302-{n.strip()}'
        assert ident not in judgements, ident
        judgements[ident] = {'id': ident, 'status': 'keep', 'whyVi': why}

def fix(ids, tip, why, reason=None, references=None):
    assert 20 <= len(tip) <= 180, (ids, len(tip))
    for n in str(ids).split(','):
        ident = f'DGT302-{n.strip()}'
        assert ident not in judgements, ident
        judgements[ident] = {'id': ident, 'status': 'fix', 'whyVi': why}
        entry = {'id': ident, 'tip': tip, 'whyVi': why}
        if reason is not None:
            entry['reason'] = reason
        if references:
            entry['references'] = references
        changes[ident] = entry

