keep('751', 'Low power/cost→fixed-point đúng yếu tố phần cứng của câu so sánh; không hứa no overflow hay no quantization.')
fix('752', 'IIR bậc cao → chia thành SOS bậc hai, tránh một đa thức dài nhạy sai số; đây là lý do chọn output="sos".', 'Stem hỏi why sos; mẹo cũ chỉ nhắc tùy chọn, chưa nêu mục đích numerical stability.')
keep('753', 'AR→Yule–Walker, target→Wiener–Hopf đúng sự khác biệt autocorrelation so với cross-correlation của bài toán ước lượng.')
fix('754', 'Đã có causal rational + mọi |pole|<1 → ROC ngoài cực ngoài cùng chứa |z|=1 → BIBO stable.', 'Mẹo cũ thêm nếu ROC còn để người học kiểm tra lại giả thiết đã suy được; nêu mạch suy luận từ causal đang có.')
fix('756', 'Upsample I chèn I−1 zero làm DC trung bình giảm I lần → LPF anti-imaging cần gain I để bù biên độ.', 'Mẹo cũ chỉ cho gain bằng I trong khi stem hỏi tại sao; thêm cơ chế giảm DC do chèn zero.')
fix('758', 'Cần dynamic range lớn → floating-point có số mũ biểu diễn cả rất nhỏ lẫn rất lớn; fixed-point chỉ có một scale.', 'Thêm đặc điểm số mũ giải thích lựa chọn thay vì chỉ ghép largest dynamic range với floating-point.')
keep('759', 'Fmax=8→Fs>16 kHz là bước tính đúng; trong các lựa chọn chỉ 20 kHz thỏa.')
keep('760', 'Low-pass giữ thấp/chặn cao là mnemonic định nghĩa đúng, đủ loại high-pass và band-pass.')
keep('761', 'Right shift→scale down tránh overflow đúng mục tiêu fixed-point, lời giải đã chỉ chia 2 tạo headroom.')
fix('762,763,764', 'Causal: ROC ngoài cực xa nhất; stable: ROC chứa |z|=1 → tất cả pole ở |z|<1 và ROC ở phía ngoài chúng.', 'Mẹo poles inside/ROC outside cũ thiếu ngoài cực nào; nêu đúng cả hai điều kiện, không lẫn ngoài vòng đơn vị.')
keep('765', 'Reflection coefficients→lattice đúng tên cấu trúc cần gọi, không nhầm twiddle FFT hay hệ số biquad.')
keep('766', 'Bandpass sampling→non-overlapping replicas đúng điều kiện quyết định, không dùng cứng Fs>2fmax.')
keep('767', 'Sau upsampling cần anti-imaging LPF là đúng lý do loại ảnh phổ trong câu; không nhầm anti-clipping hay lượng tử.')
keep('768', 'FFT speed→divide and conquer đúng chia DFT lớn thành nhỏ, không nói FFT là xấp xỉ hay giảm số bin.')
keep('769', 'Mẹo smoother spectrum→interpolation không resolution mới phân biệt đúng hiển thị với thông tin quan sát.')
fix('770', 'Downsample D: theo tần số chuẩn hóa rad/sample, phổ giãn D lần và các bản có thể chồng gây aliasing.', 'Thêm trục tần số chuẩn hóa đã có trong lời giải, tránh nhầm giãn tần số vật lý Hz của tín hiệu.')
keep('771', 'More ADC bits→better quantization SNR đúng thay đổi độ phân giải biên độ khi Fs giữ nguyên, không nhầm giảm aliasing.')
keep('772', '×(−j)→swap+sign cụ thể đúng (a+jb)(−j)=b−ja, không cần bộ nhân phức tổng quát.')
fix('773', 'H(z)→đáp ứng tần số: thay z=e^(jω), |z|=1; cần vòng đơn vị nằm trong ROC.', 'Thêm điều kiện ROC để dùng phép thế hợp lệ, thống nhất lời giải đã nêu.')
fix('774', 'Chỉ thấy các bản sao tại kFs → hệ quả lấy mẫu bình thường; chỉ khi chúng chồng nhau mới kết luận aliasing.', 'Mẹo normal sampling đúng nhưng thêm cách phân biệt aliasing là distractor dễ nhầm nhất.')
keep('775', 'One memory array→in-place là nhận biết đúng nhu cầu lưu trữ của FFT, không nhầm zero-padding.')
fix('776', 'Dữ liệu thực → X[N−k]=X*[k], suy nửa phổ từ nửa còn lại → giảm tính nhờ conjugate symmetry.', 'Câu hỏi giảm tính như thế nào; thêm quy tắc suy nửa phổ thay chỉ nhắc tên đối xứng.')
keep('777', 'Mẹo same samples→aliasing ambiguity và không cần cả hai vượt Nyquist khớp phương án thứ năm sửa nguồn.')
fix('778', 'Zero-Order Hold giữ giá trị đến mẫu tiếp → dễ làm phần cứng nhưng đầu ra thành bậc thang, không tái tạo lý tưởng.', 'Mẹo cũ chỉ staircase thiếu vế simple implementation trong trade-off được hỏi.')
fix('779', '|H| rất nhỏ → |1/H| rất lớn: inverse filter khuếch đại cả nhiễu ở tần số đó, dù H chưa bằng zero.', 'Thêm bước nghịch đảo độ lớn và giữ điều kiện nonzero để phân biệt với không tồn tại nghịch đảo.')
keep('780', 'Zero stuffing chưa là nội suy hoàn chỉnh, cần LPF loại imaging; mẹo bám đúng thiếu sót của chèn zero đơn thuần.')
keep('781', 'Whitening→decorrelation/innovation đúng loại phần dự đoán được bằng quá khứ, lời giải không nói tạo thêm thông tin.')
keep('782', '|H| biên độ và ∠H pha đúng ý nghĩa đáp ứng với sin tại ω, không lẫn năng lượng đầu vào.')
fix('783', 'Độ dài từ hữu hạn → làm tròn/cắt ở mỗi tầng tích lũy sai số; chọn precision và scale phù hợp, không phải FFT đổi năng lượng.', 'Mẹo cũ liệt kê precision/scaling/rounding mà chưa chỉ vì sao phải quản lý; thêm sai số tích lũy và loại lý do sai.')
keep('784', 'High-order implementation→cascade SOS đúng giảm numerical problems bằng tầng bậc hai, khớp lời giải.')
keep('785', '12<2×8=16 kHz đúng kiểm tra Nyquist để chọn spectral overlap, không lẫn quantization từ tăng bit.')
keep('786', 'LPF trước downsampler đúng thứ tự chống alias, lời giải đã nêu phổ gộp không tách lại được.')
keep('787', 'Missing 1/N→gain N đúng với DFT thuận không chuẩn hóa, không nhầm phase reversal hay tăng resolution.')
fix('788', 'Nếu chưa giới hạn băng thông, downsample trước làm chồng phổ; lọc sau không tách lại được alias đã xảy ra.', 'Mẹo cũ khẳng định downsample first luôn alias; thêm điều kiện dải chưa phù hợp, đúng tính most likely trong stem.')
fix('789', 'Không biết chính xác mẫu tương lai của tín hiệu random → mô tả bằng kỳ vọng, phương sai, tương quan thay một quỹ đạo xác định.', 'Câu hỏi tại sao dùng thống kê; mẹo cũ random→statistical quantities chỉ lặp lại câu hỏi, không nêu sự bất định.')
fix('790', 'Đề hỏi PSD/công suất, không phải biên độ → Syy=|H|²Sxx; có bình phương độ lớn, không phải H·Sxx.', 'Thêm cue công suất→bình phương để phân biệt hai phương án H và |H|².')
keep('792', 'Divide-and-conquer→recursive smaller DFTs là định nghĩa cụ thể đúng, không nhầm lặp cùng DFT lớn.')
keep('793', 'Parseval→conserved energy là mnemonic định lý đúng; lời giải có chuẩn hóa, không nói FFT tăng năng lượng.')
keep('794', 'Chập thời gian và tích Z là convolution theorem; mẹo Y=XH khớp quan hệ và tên định lý cần chọn.')
keep('795', 'FIR+window→firwin đúng tên hàm thiết kế, phân biệt apply lfilter và inspect freqz.')
keep('796', 'Apply FIR/IIR→lfilter là cue đúng thao tác áp dụng hệ số lên dữ liệu, chữ l thường rõ ràng.')
keep('797', 'Inspect frequency response→freqz đúng hàm phân tích, không nhầm thiết kế hay lọc tín hiệu.')
keep('798', 'Up+FIR+down→upfirdn đúng ba bước và tên hàm, lý do đã nêu tích hợp hiệu quả.')
keep('799', 'Butterworth design→butter là mnemonic cụ thể, không lẫn firwin, freqz hay lfilter.')

expected = {x['id'] for x in items}
assert set(judgements) == expected, {'missing': sorted(expected-set(judgements)), 'extra': sorted(set(judgements)-expected)}
assert len(items) == len(expected) == 298
